int dfs_centroid(int u, int p, int tot){\n    for(int v: g[u]) if(v != p && !removed[v]){\n        if(sz[v] > tot/2) return dfs_centroid(v, u, tot);\n    }\n    return u;\n}\n\n// Collect data for a subtree rooted at 'start' (child of centroid 'c')\nvoid dfs_collect(int u, int p, int depth, ll pathSum, ll sumJ, ll sumRight, ll wRight, int centroid, vector<Left>& lefts, vector<Right>& rights){\n    // Left data for endpoint p=u: depth = distance from centroid to u\n    lefts.push_back({ depth, pathSum, sumJ });\n    rights.push_back({ depth, sumRight, wRight });\n    for(int v: g[u]) if(v != p && !removed[v]){\n        dfs_collect(v, u, depth+1, pathSum + a[v], sumJ + (ll)(depth+1) * a[v], sumRight + a[v], wRight + (ll)(depth+1) * a[v], centroid, lefts, rights);\n    }\n}\n\nvoid decompose(int entry){\n    dfs_size(entry, -1);\n    int c = dfs_centroid(entry, -1, sz[entry]);\n    removed[c] = 1;\n\n    // Gather neighboring subtrees of centroid\n    vector<int> neigh;\n    for(int v: g[c]) if(!removed[v]) neigh.push_back(v);\n\n    // Initialize Li Chao hull (domain of x is pathSum, which can be up to totalSum)\n    LiChao hull(0, max(1LL, totalSum));\n    hull.clear();\n    // We will accumulate rights from subtrees, and after each subtree, insert its rights as lines.\n\n    // Forward pass: process subtrees in order\n    for(int nb : neigh){\n        vector<Left> lefts; vector<Right> rights;\n        dfs_collect(nb, c, 1, a[c] + a[nb], a[nb], a[nb], a[nb], c, lefts, rights);\n        // 1) Paths with p=c and q in this subtree: update answer directly for each right endpoint\n        for(auto &R : rights){\n            ll cand = (R.depth + 1LL) * (a[c] + R.sumRight) - R.wRight; // (R+1)*(a[c]+sumRight) - wRight\n            if(cand > answer) answer = cand;\n        }\n        // 2) Cross-subtree paths where p is in the current left subtree\n        for(auto &L : lefts){\n            ll val = L.pathSum + L.sumJ + hull.query(L.pathSum);\n            if(val > answer) answer = val;\n        }\n        // 3) Add rights of this subtree to the hull for future subtrees\n        for(auto &R : rights){\n            hull.add_line(Line(R.depth, (R.depth + 1LL) * R.sumRight - R.wRight));\n        }\n    }\n\n    // Reverse pass: handle opposite orientation of subtrees\n    hull.clear();\n    for(int idx = (int)neigh.size()-1; idx >= 0; --idx){\n        int nb = neigh[idx];\n        vector<Left> lefts; vector<Right> rights;\n        dfs_collect(nb, c, 1, a[c] + a[nb], a[nb], a[nb], a[nb], c, lefts, rights);\n        // 1) p=c contributions in this reversed order\n        for(auto &R : rights){\n            ll cand = (R.depth + 1LL) * (a[c] + R.sumRight) - R.wRight;\n            if(cand > answer) answer = cand;\n        }\n        // 2) cross-subtree with left in this subtree\n        for(auto &L : lefts){\n            ll val = L.pathSum + L.sumJ + hull.query(L.pathSum);\n            if(val > answer) answer = val;\n        }\n        // 3) insert rights into hull for future iterations\n        for(auto &R : rights){\n            hull.add_line(Line(R.depth, (R.depth + 1LL) * R.sumRight - R.wRight));\n        }\n    }\n\n    // Recurse into each subtree\n    for(int nb : neigh) decompose(nb);\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    if(!(cin >> n)) return 0;\n    g.assign(n, {});\n    for(int i=0;i<n-1;i++){\n        int u,v; cin >> u >> v; --u; --v;\n        g[u].push_back(v); g[v].push_back(u);\n    }\n    a.assign(n, 0);\n    totalSum = 0;\n    ll mx = 0;\n    for(int i=0;i<n;i++){ ll x; cin >> x; a[i] = x; totalSum += x; mx = max(mx, x); }\n    // Initial answer could be a single node path\n    answer = mx;\n\n    sz.assign(n, 0);\n    removed.assign(n, 0);\n    decompose(0);\n    cout << answer << \"\\n\";\n    return 0;\n}\nCPP\n",
